#include <stdio.h>
#include <stdlib.h>

int *make_box(int value) {
    int *p = (int *)malloc(sizeof(int));
    if (p == NULL) {
        return NULL;
    }
    *p = value;
    return p;
}

int main(void) {
    int *box = make_box({v});
    if (box == NULL) {
        printf("仓库没租到喵\n");
        return 1;
    }
    printf("盒子里装着 %d\n", *box);
    free(box);
    box = NULL;
    printf("还掉之后，牌子也收起来了\n");
    return 0;
}
